func (r *Reporter) loadState() error {
	contents, err := os.ReadFile(r.statePath)
	if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("reading telemetry state: %w", err)
	}
	if err == nil && json.Unmarshal(contents, &r.state) != nil {
		r.state = State{}
